WITH runs AS (SELECT case_id, MAX(CASE WHEN run_role='CURRENT' THEN run_id END) current_run_id, MAX(CASE WHEN run_role='PREVIOUS' THEN run_id END) previous_run_id, MAX(CASE WHEN run_role='CURRENT' THEN formula_id END) current_formula_id, MAX(CASE WHEN run_role='PREVIOUS' THEN formula_id END) previous_formula_id, MAX(CASE WHEN run_role='CURRENT' THEN formula_hash END) current_formula_hash, MAX(CASE WHEN run_role='PREVIOUS' THEN formula_hash END) previous_formula_hash FROM {{PUBLIC}}.datapoint_result GROUP BY case_id)
SELECT c.*, r.current_run_id, r.previous_run_id, r.current_formula_id, r.previous_formula_id, r.current_formula_hash, r.previous_formula_hash FROM {{PUBLIC}}.case_definition c JOIN runs r USING (case_id) WHERE c.status='ACTIVE'
